import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"萃","description":"高岛易断 - 萃","frontmatter":{"title":"萃","description":"高岛易断 - 萃"},"headers":[],"relativePath":"zh/classics/takashima/045.md","filePath":"zh/classics/takashima/045.md"}'),i={name:"zh/classics/takashima/045.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><h2 id="萃-1" tabindex="-1">萃 <a class="header-anchor" href="#萃-1" aria-label="Permalink to “萃”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>萃：王假有庙，利见大人。亨，利贞。用大牲吉，利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《萃》与《涣》名相反，而义则相须。《涣》之亨，取诸水流风行；《萃》之亨，取诸《兑》悦《坤》顺。《涣》亦假庙，《涣》之假庙，见神气之发扬；《萃》之假庙，见精诚之贯注：一散一聚，义各不同，而所以致诚者一也。王者合万国之欢心，以事其祖考，侯助男卫，骏奔在庙，是《萃》之盛也。“大人”谓九五，五“萃有位”，能御众以治乱，故“利见”。“亨，利贞”者，《兑》曰“亨，利贞”，《坤》曰“柔顺利贞”，盖即从《坤》《兑》来也。《坤》为牛，亦为用，故曰“用大牲”，言大人有嘉会，必杀牛而盟；既盟则可以往，故曰“利有攸往”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>泽上于地，萃。君子以除戎器，戒不虞。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《兑》为金，《坤》为器，有戎器之象。“除”，修治也，修治戎器，以防不虞，所谓有备无患也。卦象为泽上于地，水满则溢，溃决奔突，势莫能御，所当预为之防；水犹兵也，故可借鉴。按《穆天子传》：有七《萃》之士，取宿卫环聚为名，是《萃》为防御之士，所以遏乱也。《萃》象之“除戎器”，义盖取此耳。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：气运平顺，但能安不忘危，自得欢乐无忧。</p><p>○　问战征：兵凶器，战危事，惟能临事而惧，好谋而成，可无意外之虞也。</p><p>○　问营商：《萃》有财聚之象，然聚必有散，盈必有亏，亦理之循环，所当时时预防。</p><p>○　问功名：宜由武功得名。</p><p>○　问婚姻：“匪寇婚媾”，《易》每以寇婚对言，盖防兵祸，犹防女祸也。惟能预防，自可无咎。</p><p>○　问家宅：泽上于水，防有大水入屋之象。</p><p>○　问疾病：防胸腹有水胀之症，宜预为调治。</p><p>○　问行人：中途兵阻，一时难归。</p><p>○　问六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>《兑》为孚，故“有孚”；《坤》为终，初失位，故“不终”；《坤》为聚，亦为乱，故曰“乃乱乃萃”。初为《萃》之始，相孚犹浅，是以有初鲜终也；不得其终，则一念萃于此，易一念而萃于彼，其志先乱矣，是萃适以长乱也。《象传》以“志乱”释之，“乃”犹汝也，汝自萃之，汝自乱之也。初爻阴柔居下，虽得众，未足以总之；初与四应，则御萃之权，当在四也。“若”，顺也，“号”，令也，谓顺从四之号令。“一握为笑”，谓推诚相与，众皆欢悦，即《彖传》所云“顺以悦”也。上互《巽》，《巽》为号，下互《艮》，《艮》为执，执手，犹握手，退之所谓“握手出肺肝相示”者是也。《兑》为口，故曰“笑”，既得其笑，故“勿恤”。“往”，往四也，四能恩威并著，初自不致乌合为乱也，故“无咎”。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：运当初交，一顺一逆，反复无常，得所救援，可以无咎。</p><p>○　问功名：忽荣忽辱，由于中心无主也。</p><p>○　问营商：有初无终，聚散不定，不能获利，仅可免咎而已。</p><p>○　问战征：统军出征，防有兵变之忧。</p><p>○　问婚姻：有始乱之，而终娶之之象。</p><p>○　问疾病：此病忽号忽笑，由于心神昏乱，往而求医，必无咎也。可勿忧。</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治十五年十月，大水陡发，上野高崎间铁道所辖户田川口假桥，致被冲塌。余曾执司工事，往晤铁道局长井上君，井上君曰：川口假桥冲裂，铁道被梗，不得不急议修筑。按川口堤岸，高出平地丈余，若架造坚固铁桥，工程既大，经费亦巨，若仍筑假桥，一经发水，便遭冲决，亦非善策，若何而可？请为筹度。余曰：不如问诸神易。乃筮得《萃》之《随》。</p><p>断曰：此卦泽上于地，明示洪水泛滥之象。占得初爻，知此假桥建筑不久，乍筑乍倾，故谓之“有孚不终，乃乱乃萃”。初正应在四，宜听令于四。“若号”者，四之号令也；“握”，犹执也。得四之号令，众皆欢欣，愿执其役，《兑》为悦，所谓“悦以劳民，民忘其劳”也，故曰“一握为笑”。但四不当位，则必桥之地位不当，五曰“萃有位”，则位宜从五。五变为《豫》，《豫》者有《豫》备之义，《豫》卦《震》上《坤》下，《萃》为《兑》上，《兑》西《震》东，易《兑》为《震》，桥宜改西从东方为当位。《坤》地在下，《坤》为厚，为基，宜从平地培土为基，营架一桥，再设铁索，系锁于两堤，水来随高，水落随平，使无冲溃奔突之患，故得“无咎”。井上君闻之，亦以为然，众议乃决，依此作桥。翌年水复大发，桥得无患，益叹《易》象之神也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二居下卦之中，上应于五，知《萃》之当归于五也。二与初、三为同体，初之“乱”，三之“嗟”，是失所《萃》也，二能引之，同《萃》于五，故曰“引吉，无咎”。上互《巽》，《巽》为绳，下互《艮》，《艮》为手，有引之象。“禴”，夏祭名，六二为《离》爻，《离》南方，为夏，故“利用禴”。二动体《困》，《困》二曰“利用享祀”，《萃》反为《升》，《升》二亦曰“利用禴”，以二得中，故其象同也。《彖》称假庙用牲，二为助祭，助祭当献方物，《坤》为吝啬，故薄，然输诚来《萃》，虽薄亦孚，孚，固不在多仪也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：运得正中，吉。</p><p>○　问功名：可望汲引而进。</p><p>○　问营商：“引”，牵引也，想是合众生意，必可获吉，但须答愿酬神。</p><p>○　问战征：古者出师必祭，于内曰类，于野曰冯是也，盖祭神以誓师也。吉。</p><p>○　问婚姻：二应于五，是二五订婚也，故曰“引吉”。</p><p>○　问疾病：仙人辟谷之法，曰引导，为引运其元气，使之充实无亏，即可却疾。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>友人某来，请占气运，筮得《萃》之《困》。</p><p>断曰：此卦地上有泽，可以蓄水，即可聚财，故卦曰《萃》。今占得二爻，爻辞曰“引吉”，知足下所谋之事，必待有人引而伸之，乃可获吉。二与五应，能为足下指引者，必属于五。惜其中有三四两爻间隔，宜备礼祈祷，以乞神祐，使三四不能阻碍，则所谋得遂，自然吉而无咎也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三处《坤》之上，《坤》为众，得《萃》之象。盖《萃》必众心欢悦，其《萃》乃为可用，三以阴居阳，不能统率《坤》众。《萃》者以利而《萃》，《萃》而无利，则《萃》者嗟矣，故曰“萃如嗟如”。卦以五爻为《萃》之宗主，即《彖》所称“利见”之“大人”也，往而归之，有攸利焉。“小吝”者，三无御《萃》之才，致腾众口，为可鄙耳。《传》曰“上巽也”，《萃》上互《巽》，《巽》五曰“无不利”，谓往而可得《巽》之利也。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：运途平平，无可获利也。</p><p>○　问功名：功名不利，反被人鄙。</p><p>○　问营商：货物虽多，不售可嗟，何所获利？惟转运他处，可得无咎。</p><p>○　问战征：有兵而不得其用，反致怨嗟，在主将无御众之才也。</p><p>○　问婚姻：未免兴怨偶之嗟。</p><p>○　问家宅：同居不睦，致多口舌，往迁可以无咎。</p><p>○　问疾病：胸膈积滞作痛，致声声叫苦，以两便不利所致，利则可以无咎。</p><p>○　问讼事：不利。</p><p>○　问六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>友人来，请占气运，筮得《萃》之《咸》。</p><p>断曰：卦体上悦下顺，众人归附，占象得此，可为佳矣。今占得第三爻，三爻以阴居阳，自无御众之才，无以利众，以致众怨，故曰“萃如嗟如，无攸利”。知足下身任副局长，不得众心，爻辞之言，若适为足下发也。足下当令其往附于局长，斯众得其利，而可无咎矣。《象》曰“上巽”，巽顺也，在足下运途亦顺矣。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四出《坤》入《兑》，当内外卦之交，为多惧之地，初应之，三比之，开馆招宾，礼贤下士，如汉之王莽曹操，臣而得众，凶莫大焉。爻曰“大吉，无咎”，必其克尽“大吉”之道，乃得“无咎”；必其能立“无咎”之地，乃得“大吉”。若文王三分有二以服事殷，能有其萃，而不自以为萃，必率其萃而归之于君，斯可谓大吉而无咎矣。《象传》于“大吉，无咎”，而犹以“位不当”释之，其旨严矣！</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：气运大好，无往不吉，但于地位不当，宜慎。</p><p>○　问功名：大吉，但恐德不称位。</p><p>○　问营商：得财得利大吉；宜作退一步想，方能有始有终。</p><p>○　问战征：战胜攻克，大吉大利；防功高震主，谤毁随之。</p><p>○　问婚姻：四与初为正应，即为正配，吉；但门第恐不甚相当也。</p><p>○　问家宅：此宅人口兴旺，家室平安，大吉；但地位少嫌卑下。</p><p>○　问疾病：是外强中干之症，目下可保无咎。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>某家支配人，请占气运，筮得《萃》之《比》。</p><p>断曰：凡占卦取爻辞，亦当兼取爻象，往往有爻辞则吉，而爻象则凶者，亦有爻象则凶，而爻辞则吉者。今此爻之辞曰“大吉，无咎”，《象传》曰“位不当”，未免于吉中有凶。足下占气运得此爻，在足下身任支配，凡主家之权利，皆归足下担负，一时趋附权利者，不必归向于主家，必皆归向于足下，此亦势之所必然也。于是足下之名大震，足下之运大盛，安得不谓之“大吉”哉！其实此等权利，皆主家所有，非足下所可自有也，《象传》以“位不当”戒之，足下最宜凛凛焉。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五居尊位，为《萃》之主，故曰“萃有位”；居其位以御其众，故“无咎”。然亿兆之归往在有位，亦不仅在有位也，要必有足以服众者，而众乃中心诚服矣。是《萃》以位，实《萃》以德，以德服人，此之谓“孚”，若徒曰“萃有位”而已，是以权位胁取，非心服也，孚何有焉？“非孚”而《萃》，后且有悔。“元永贞”者，《乾》《坤》之德也，“元”者，《乾》之“长人”，“永贞”者，《坤》之载物，既具此德，则德位兼备，群黎百姓，罔不相应，悔自亡矣。《象传》曰“志未光”，为徒有其位言之耳。按：《比》《彖》亦曰“元永贞”，《比》以一阳统众阴，故“元永贞”言于卦；《萃》虽有二阳而统众阴者，以五为主，故“元永贞”言于五。义各有当也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：得位得权，运当全盛，自可无咎。</p><p>○　问营商：财则聚矣，信尚未也，能守其正，业自可久。</p><p>○　问功名：位则高矣，望则隆矣，更宜修德履正。</p><p>○　问战征：三军既集，大业可成，更宜推诚相与，可保永终。</p><p>○　问婚姻：位尊金多，可称贵婿。</p><p>○　问家宅：此宅地位，山环水聚，聚族而居，吉。</p><p>○　问疾病：心神不定，宜静养。</p><p>○　问讼事：以讼者爵位隆，声势盛，虽枉得直。</p><p>○　问六甲：生女。</p><p>○　问失物：久后可得，无咎。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>一日友人来，请占气运，筮得《萃》之《豫》。</p><p>断曰：五爻为《萃》之主，既有其位，又有其众，运无咎也。足下占气运，得此爻象，知足下非卑下之俦，有位有财，非一乡之望，即一家之主也。特一时信义未孚，在众人或怀疑虑，当履道守正，久而不失，斯言寡尤，行寡悔，而万事亨通矣。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“赍咨”，嗟叹之辞。目出曰涕，鼻出曰洟，“赍咨涕洟”，悲泣之状也。上爻阴柔不中，居《萃》之极，三与上为敌应，敌应则无《萃》，孤立于上而安得安乎？知其不安，则忧之深，虑之甚，极之“赍咨涕洟”，悲愁百结，人亦当谅其哀怨而来《萃》也，故得“无咎”。皖江陈氏以“咨”为资财，“赍”为持，谓财聚民散，是有其财而不能有其众，则坐拥厚资，适以自危，如鹿台巨桥，卒供兴王之恩赏，此诚当痛哭流涕者也。其说亦亲切。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：人必年老运退，极至穷极悲苦，为可悯也。然必有怜而救援者，得以无咎。</p><p>○　问营商：孤客无伴，途穷日暮，大可悲虑，幸而得救，无咎。</p><p>○　问功名：时衰运极，难望成名。</p><p>○　问战征：有军众叛离，主将孤立之象。</p><p>○　问婚姻：有生离死别之悲。</p><p>○　问家宅：仳离啜泣，家室不安。</p><p>○　问疾病：病自悲泣过甚而来，宜宽怀调养。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十一年六月，余为谋设摄绵土制造厂，游寓爱知热田，偶过热田神宫，得晤神职某氏，相与讲《易》。时际旱魃，乡农数百，赛社祈雨，余语神职某曰：乡人诚求，神其谆谆然命之乎？神职曰：神何言哉！余曰：神固不言，有足以通神之言者，其惟《易》乎？曷不筮之？筮得《萃》之《否》。</p><p>断曰：此卦上卦之泽，为受水之地，泽出地上，有泽满水溢之象。爻辞曰“赍咨”，在人为悲怨之情，在天为震怒之声，即迅雷也；曰“涕洟”，在人为悲泣之状，在天为滂沱之泽，即大雨也。当此迅雷大雨，洪水暴作，人民罹灾，神亦为之不安，故《象》曰“未安上也”。计其时日，自初至上为六日，当必有验。时七月十六日也，闻者多未之信。届期天日晴朗，大宫司角田氏谓余曰：大雨之期，占在今日，恐不验也。余曰：余惟就占论占，验不验非余所知，然向来所占，未有不验也。至午后，云涌风起，迄三时，雷公电母，风伯雨师，数驾齐来，顷刻之间，沟浍充盈，平地皆水，于是官司等，惊骇感服，过余称谢。翌年伊藤议长佐野顾问赛热田神宫，向官司诸人询问余占雨神验，官司即以断辞上申。两公大感神德之灵应，详询热田神社始祀之由，后宫内省发给祠币十万元，社格列伊势大庙之次。</p>',105)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
